"use client";

/**
 * Photo reel: an opening caption, then pictures cut fast, full frame, with the
 * last one slowly zooming. The frame then closes into a neat collage of every
 * picture under a closing caption.
 *
 * Written by Better Design. Painted from the theme prop; with no pictures each
 * cut shows a landscape placeholder drawn from the primary colour.
 */
import { loadFont } from "@remotion/google-fonts/Inter";
import { AbsoluteFill, Img, interpolate, useCurrentFrame } from "remotion";
import { easings, mix, pickFont, progress, shiftHue, type VideoTheme, useVideoTheme, withAlpha, srcOf } from "@/lib/bd-video";

/** A bare file name resolves from the project's public folder; a URL or root path passes through. */

const { fontFamily: INTER } = loadFont("normal", { weights: ["500", "700"], subsets: ["latin"] });

const CUTS_AT = 30;
/** Frames each fast cut holds. */
const CUT = 6;
const HOLD = 32;
const CLOSE_FRAMES = 26;
const PLACEHOLDERS = 6;
const COLS = 3;
const CELL_W = 384;
const CELL_H = 216;
const GAP = 24;
const GRID_TOP = 236;

/** Fixed paper and ink for placeholder photos, so they read the same in both modes. */
const LIGHT = "oklch(0.97 0.015 85)";
const DEEP = "oklch(0.3 0.05 60)";

export interface PhotoReelProps {
  /** The line before the first cut. */
  openingCaption?: string;
  /** The line under the collage at the end. */
  closingCaption?: string;
  /** Image URLs or static files, cut in order. Six fill the collage neatly. */
  pictures?: string[];
  theme?: Partial<VideoTheme>;
  /** A CSS font family the project has loaded. Defaults to the theme's face, then Inter. */
  font?: string;
}

/** A landscape drawn from the theme, sized in percent so it reads full frame and small. */
function PlaceholderPhoto({ theme, index }: { theme: VideoTheme; index: number }) {
  const base = shiftHue(theme.primary, index * 61 - 30);
  return (
    <div style={{ position: "absolute", inset: 0, overflow: "hidden", background: `linear-gradient(170deg, ${mix(base, LIGHT, 0.64)}, ${mix(base, LIGHT, 0.16)})` }}>
      <div style={{ position: "absolute", width: "16%", aspectRatio: "1", borderRadius: "50%", left: `${14 + (index * 31) % 60}%`, top: "15%", background: mix(base, LIGHT, 0.9) }} />
      <div style={{ position: "absolute", left: "-20%", right: "25%", bottom: "-48%", height: "92%", borderRadius: "50%", background: mix(base, DEEP, 0.26) }} />
      <div style={{ position: "absolute", left: "35%", right: "-30%", bottom: "-60%", height: "94%", borderRadius: "50%", background: mix(base, DEEP, 0.5) }} />
    </div>
  );
}

/** Fast full-frame cuts between two captions, closing into a collage grid. */
export function PhotoReel({
  openingCaption = "One week on the road",
  closingCaption = "Every frame, kept together",
  pictures = [],
  theme: themeOverride,
  font,
}: PhotoReelProps) {
  const theme = useVideoTheme(themeOverride);
  const frame = useCurrentFrame();
  const family = pickFont(font, theme, INTER);
  const count = pictures.length > 0 ? pictures.length : PLACEHOLDERS;
  const last = count - 1;

  const lastAt = CUTS_AT + last * CUT;
  const closeAt = lastAt + HOLD;
  const rows = Math.ceil(count / COLS);
  const gridW = COLS * CELL_W + (COLS - 1) * GAP;
  const cell = (i: number) => {
    const row = Math.floor(i / COLS);
    const inRow = row === rows - 1 ? count - row * COLS : COLS;
    const rowLeft = (1920 - (inRow * CELL_W + (inRow - 1) * GAP)) / 2;
    return { left: rowLeft + (i - row * COLS) * (CELL_W + GAP), top: GRID_TOP + row * (CELL_H + GAP) };
  };

  const picture = (index: number) =>
    pictures.length > 0 ? (
      <Img src={srcOf(pictures[index])} style={{ position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "cover" }} />
    ) : (
      <PlaceholderPhoto theme={theme} index={index} />
    );

  const openIn = easings.out(progress(frame, 2, 16));
  const showOpening = frame < CUTS_AT;
  const current = Math.min(last, Math.floor((frame - CUTS_AT) / CUT));
  const fastCut = frame >= CUTS_AT && current < last;

  const close = easings.inOut(progress(frame, closeAt, CLOSE_FRAMES));
  const slowZoom = interpolate(progress(frame, lastAt, HOLD), [0, 1], [1, 1.1]);
  const heroZoom = interpolate(close, [0, 1], [slowZoom, 1]);
  const target = cell(last);
  const hero = {
    left: interpolate(close, [0, 1], [0, target.left]),
    top: interpolate(close, [0, 1], [0, target.top]),
    width: interpolate(close, [0, 1], [1920, CELL_W]),
    height: interpolate(close, [0, 1], [1080, CELL_H]),
  };
  const captionT = easings.out(progress(frame, closeAt + 18, 18));

  return (
    <AbsoluteFill style={{ background: theme.background, fontFamily: family, overflow: "hidden" }}>
      {showOpening && (
        <AbsoluteFill style={{ alignItems: "center", justifyContent: "center" }}>
          <div style={{ fontSize: 96, fontWeight: 700, letterSpacing: "-0.035em", color: theme.foreground, opacity: openIn, transform: `translateY(${(1 - openIn) * 20}px)` }}>
            {openingCaption}
          </div>
        </AbsoluteFill>
      )}
      {fastCut && <AbsoluteFill>{picture(current)}</AbsoluteFill>}
      {frame >= closeAt &&
        Array.from({ length: last }, (_, i) => {
          const t = easings.out(progress(frame, closeAt + 8 + i * 3, 16));
          const { left, top } = cell(i);
          return (
            <div
              key={i}
              style={{
                position: "absolute",
                left,
                top,
                width: CELL_W,
                height: CELL_H,
                borderRadius: theme.radius * 1.2,
                overflow: "hidden",
                opacity: t,
                transform: `scale(${interpolate(t, [0, 1], [0.86, 1])})`,
                boxShadow: `0 16px 40px oklch(0 0 0 / 0.12)`,
              }}
            >
              {picture(i)}
            </div>
          );
        })}
      {frame >= lastAt && (
        <div
          style={{
            position: "absolute",
            ...hero,
            borderRadius: theme.radius * 1.2 * close,
            overflow: "hidden",
            boxShadow: close > 0 ? `0 16px 40px oklch(0 0 0 / ${0.12 * close})` : "none",
          }}
        >
          <div style={{ position: "absolute", inset: 0, transform: `scale(${heroZoom})` }}>{picture(last)}</div>
        </div>
      )}
      <div
        style={{
          position: "absolute",
          left: (1920 - gridW) / 2,
          width: gridW,
          top: GRID_TOP + rows * CELL_H + (rows - 1) * GAP + 64,
          textAlign: "center",
          fontSize: 60,
          fontWeight: 700,
          letterSpacing: "-0.03em",
          color: theme.foreground,
          opacity: captionT,
          transform: `translateY(${(1 - captionT) * 16}px)`,
        }}
      >
        {closingCaption}
      </div>
    </AbsoluteFill>
  );
}
